create table if not exists dori_war_games (id uuid primary key default gen_random_uuid(), room_code text unique not null, state jsonb not null, created_at timestamptz default now()); alter table dori_war_games enable row level security; create policy "public read" on dori_war_games for select using (true); create policy "public insert" on dori_war_games for insert with check (true); create policy "public update" on dori_war_games for update using (true);